1	// PhishSense game logic (runs in the browser)
2	
3	const ROUNDS = 5;        // rounds per mode
4	const TO_PASS = 4;       // correct answers needed for the badge
5	const PER_CORRECT = 100; // points per correct answer
6	const BADGES = { easy: "Minnow", medium: "Angler", hard: "Captain" };
7	const ALL_MODES = ["easy", "medium", "hard"];
8	
9	// Badge icons: simple inline SVGs drawn in currentColor, so each one takes
10	// its difficulty color from CSS (.tier-easy green, .tier-medium yellow, .tier-hard red).
11	const BADGE_SVG = {
12	  // Minnow: a small fish
13	  easy: `<ellipse cx="13.5" cy="12" rx="7.5" ry="4.8" fill="currentColor"/>
14	    <path d="M7 12 1.5 7v10z" fill="currentColor"/>
15	    <circle cx="17" cy="10.8" r="1.1" fill="#0a1a33"/>`,
16	  // Angler: a fishing rod with its line and hook
17	  medium: `<g fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round">
18	    <path d="M3 21 19 3" stroke-width="2.4"/>
19	    <circle cx="7" cy="16.5" r="2.2" stroke-width="2"/>
20	    <path d="M19 3v11.5" stroke-width="1.3"/>
21	    <path d="M19 14.5v2.3a2.2 2.2 0 0 1-4.4 0v-.8" stroke-width="2"/></g>`,
22	  // Captain: an anchor
23	  hard: `<g fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
24	    <circle cx="12" cy="4.6" r="2.2"/>
25	    <path d="M12 6.8V21M8 10h8M4.5 13.5c0 4.3 3.2 7.5 7.5 7.5s7.5-3.2 7.5-7.5"/>
26	    <path d="M2.5 15.5l2-2 2 2M17.5 15.5l2-2 2 2"/></g>`,
27	};
28	const badgeIcon = (m) =>
29	  `<svg class="badge-icon tier-${m}" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${BADGE_SVG[m]}</svg>`;
30	// Icon + name, e.g. for "You earned [fish] Minnow!"
31	const badgeLabel = (m) => `<span class="badge-label tier-${m}">${badgeIcon(m)}${BADGES[m]}</span>`;
32	
33	// Fill every placeholder like <span data-badge-icon="easy"> (the difficulty buttons)
34	document.querySelectorAll("[data-badge-icon]").forEach((el) => (el.innerHTML = badgeIcon(el.dataset.badgeIcon)));
35	const MISSIONS = {
36	  easy: "Warm-up shift. These scams are obvious: watch for typos, surprise prizes, and ALL CAPS urgency.",
37	  medium: "Scammers are getting smarter. Check every sender address and phone number against the real ones above.",
38	  hard: "Expert level. Some scams look perfect, and some real emails look scary. Read every detail before you decide.",
39	};
40	
41	// The real addresses players check every message against.
42	const TRUSTED = [
43	  { name: "Bayline Energy", note: "your company", domain: "bayline-energy.com", phone: "(404) 555-0100" },
44	  { name: "NewsNow", domain: "newsnow.com" },
45	  { name: "ConnectPro", domain: "connectpro.com" },
46	  { name: "TechHub", domain: "techhub.com" },
47	];
48	
49	let mode, round, correct, current, seen;
50	let results;  // one entry per round: true (correct) or false (wrong)
51	let streak;   // correct answers in a row, resets on a wrong answer
52	let missed;   // every red flag from the rounds the player got wrong
53	
54	const $ = (id) => document.getElementById(id);
55	const show = (id) => {
56	  ["start-screen", "mission-screen", "play-screen", "end-screen"].forEach((s) => $(s).classList.add("hidden"));
57	  $(id).classList.remove("hidden");
58	  // style.css uses this to pick the big header or the slim top bar,
59	  // and to show the leaderboard only on the home and end screens.
60	  document.body.dataset.screen = id;
61	  window.scrollTo(0, 0);
62	};
63	const esc = (t) => String(t ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
64	
65	// Players who ask for less motion get the same game with the animations off.
66	const calmMode = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;
67	
68	// ---------- Talking to the backend ----------
69	// Practice mode: if the backend isn't running (opened as a file, Live Server,
70	// or a static host like Vercel), the game uses mock-data.js instead.
71	let OFFLINE = location.protocol === "file:";
72	
73	async function checkBackend() {
74	  if (OFFLINE) return;
75	  try {
76	    const r = await fetch("/api/leaderboard");
77	    if (!r.ok) throw new Error("no backend");
78	    await r.json();
79	  } catch (e) {
80	    OFFLINE = true;
81	  }
82	}
83	
84	async function apiGetScenario(mode, seen) {
85	  if (OFFLINE) {
86	    const pool = MOCK_SCENARIOS.filter((s) => s.difficulty === mode && !seen.includes(s.scenario_id));
87	    const s = pool[Math.floor(Math.random() * pool.length)];
88	    return { scenario_id: s.scenario_id, channel: s.channel, sender: s.sender, subject: s.subject, body: s.body, link: s.link };
89	  }
90	  return fetch(`/api/scenario?mode=${mode}&seen=${seen.join(",")}`).then((r) => r.json());
91	}
92	
93	async function apiAnswer(scenario_id, guess) {
94	  if (OFFLINE) {
95	    const s = MOCK_SCENARIOS.find((x) => x.scenario_id === scenario_id);
96	    return { correct: guess === s.game_answer, game_answer: s.game_answer, red_flags: s.red_flags, explanation: s.explanation };
97	  }
98	  return fetch("/api/answer", {
99	    method: "POST",
100	    headers: { "Content-Type": "application/json" },
101	    body: JSON.stringify({ scenario_id, guess }),
102	  }).then((r) => r.json());
103	}
104	
105	async function apiSaveScore(username, points, badge) {
106	  if (OFFLINE) {
107	    const board = JSON.parse(localStorage.getItem("ps-board") || "{}");
108	    const p = board[username] || { username, total_score: 0, badges: [] };
109	    p.total_score += points;
110	    if (badge && !p.badges.includes(badge)) p.badges.push(badge);
111	    board[username] = p;
112	    try { localStorage.setItem("ps-board", JSON.stringify(board)); } catch (e) {}
113	    return p;
114	  }
115	  return fetch("/api/score", {
116	    method: "POST",
117	    headers: { "Content-Type": "application/json" },
118	    body: JSON.stringify({ username, points, badge }),
119	  }).then((r) => r.json());
120	}
121	
122	async function apiLeaderboard() {
123	  if (OFFLINE) {
124	    let board = {};
125	    try { board = JSON.parse(localStorage.getItem("ps-board") || "{}"); } catch (e) {}
126	    return Object.values(board)
127	      .sort((a, b) => b.badges.length - a.badges.length || b.total_score - a.total_score)
128	      .slice(0, 10);
129	  }
130	  return fetch("/api/leaderboard").then((r) => r.json());
131	}
132	
133	// ---------- Trusted contacts ----------
134	// One list, shown on the mission briefing and in the panel during play.
135	function contactsHTML() {
136	  const rows = TRUSTED.map((c) => `<tr>
137	      <th scope="row">${esc(c.name)}${c.note ? `<small>${esc(c.note)}</small>` : ""}</th>
138	      <td><span class="contact-domain">${esc(c.domain)}</span>${c.phone ? `<span class="contact-phone">${esc(c.phone)}</span>` : ""}</td>
139	    </tr>`).join("");
140	  return `<table class="contacts-table">
141	      <thead><tr><th scope="col">Company</th><th scope="col">Real website &amp; phone</th></tr></thead>
142	      <tbody>${rows}</tbody>
143	    </table>
144	    <p class="contacts-tip">Scammers use names you trust with addresses that don't match. Always compare.</p>`;
145	}
146	document.querySelectorAll(".contacts-list").forEach((el) => (el.innerHTML = contactsHTML()));
147	
148	function setContactsOpen(open) {
149	  $("contacts-panel").classList.toggle("hidden", !open);
150	  $("btn-contacts").setAttribute("aria-expanded", String(open));
151	  $("btn-contacts").classList.toggle("open", open);
152	}
153	$("btn-contacts").addEventListener("click", () =>
154	  setContactsOpen($("contacts-panel").classList.contains("hidden")));
155	document.addEventListener("keydown", (e) => {
156	  if (e.key === "Escape" && !$("contacts-panel").classList.contains("hidden")) {
157	    setContactsOpen(false);
158	    $("btn-contacts").focus();
159	  }
160	});
161	
162	// ---------- Start: pick a difficulty, then see the mission ----------
163	document.querySelectorAll(".mode").forEach((btn) =>
164	  btn.addEventListener("click", () => {
165	    if (!$("username").value.trim()) return $("username").focus();
166	    mode = btn.dataset.mode;
167	    const label = mode.charAt(0).toUpperCase() + mode.slice(1);
168	    $("mission-mode").className = `mission-mode tier-${mode}`;
169	    $("mission-mode").innerHTML = `${label} mode · ${badgeIcon(mode)}${BADGES[mode]} badge`;
170	    $("mission-tip").textContent = MISSIONS[mode];
171	    show("mission-screen");
172	  })
173	);
174	
175	$("btn-back").addEventListener("click", () => show("start-screen"));
176	
177	$("btn-start").addEventListener("click", () => {
178	  round = 0;
179	  correct = 0;
180	  seen = [];
181	  results = [];
182	  streak = 0;
183	  missed = [];
184	  $("recap").classList.add("hidden");
185	  $("badge-reveal").classList.add("hidden");
186	  $("confetti").innerHTML = "";
187	  setContactsOpen(false);
188	  show("play-screen");
189	  nextRound();
190	});
191	
192	// ---------- Progress dots + streak ----------
193	function renderDots() {
194	  let html = "";
195	  for (let i = 0; i < ROUNDS; i++) {
196	    let cls = "";
197	    if (results[i] === true) cls = "correct";
198	    else if (results[i] === false) cls = "wrong";
199	    else if (i === round - 1) cls = "current";
200	    html += `<span class="dot ${cls}"></span>`;
201	  }
202	  $("dots").innerHTML = html;
203	  $("dots").setAttribute("aria-label", `Round ${Math.min(round, ROUNDS)} of ${ROUNDS}, ${correct} correct`);
204	}
205	
206	// Only worth celebrating from 2 in a row; the label stays hidden until then.
207	function renderStreak() {
208	  $("streak").textContent = streak >= 2 ? `🔥 ${streak} in a row` : "";
209	}
210	
211	// ---------- Play ----------
212	async function nextRound() {
213	  await ready;
214	  round++;
215	  $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
216	  $("result").classList.add("hidden");
217	  $("btn-next").classList.add("hidden");
218	  $("btn-phish").disabled = $("btn-legit").disabled = true;
219	  $("message").className = "ps-card";   // clears the glow or shake from the last round
220	  $("message").style.transformOrigin = "";
221	  $("pop-layer").innerHTML = "";
222	  $("reaction").className = "reaction hidden";
223	  $("reaction").textContent = "";
224	  hidePeek();
225	  renderDots();
226	  renderStreak();
227	  $("message").innerHTML = `<p class="loading">Loading message...</p>`;
228	
229	  current = await apiGetScenario(mode, seen);
230	  seen.push(current.scenario_id);
231	  $("message").innerHTML = renderMessage(current);
232	  $("btn-phish").disabled = $("btn-legit").disabled = false;
233	}
234	
235	// A steady clock time per scenario, so the inbox and phone look real
236	// without the time jumping around every time you re-read a message.
237	function clockFor(s) {
238	  const id = Math.abs(Number(s.scenario_id) || 0);
239	  const hour24 = 8 + ((id * 3) % 9);          // 8 AM to 4 PM
240	  const minute = String((id * 17) % 60).padStart(2, "0");
241	  const hour12 = hour24 % 12 === 0 ? 12 : hour24 % 12;
242	  return { short: `${hour12}:${minute}`, long: `${hour12}:${minute} ${hour24 < 12 ? "AM" : "PM"}` };
243	}
244	
245	const initialOf = (sender) => {
246	  const m = String(sender || "").match(/[a-z]/i);
247	  return m ? m[0].toUpperCase() : "?";
248	};
249	
250	// ---------- Hover to inspect links ----------
251	// Emails hide the real address behind friendly text, the way real phishing
252	// does. Hovering (or tapping) shows where the link really goes. The link is a
253	// plain button, so it can never open anything.
254	const LINK_LABELS = [
255	  [/\.exe|download|update/i, "Download the update"],
256	  [/claim|winner|prize|reward/i, "Claim your reward"],
257	  [/sign-?in|log-?in/i, "Sign in to your account"],
258	  [/verify/i, "Verify your account"],
259	  [/confirm/i, "Confirm now"],
260	  [/billing|invoice|payment/i, "View billing details"],
261	  [/video|watch/i, "Watch now"],
262	  [/story|news|article/i, "Read the full story"],
263	];
264	
265	function parseLink(raw) {
266	  const text = String(raw || "").trim();
267	  try {
268	    const u = new URL(/^[a-z]+:\/\//i.test(text) ? text : `http://${text}`);
269	    const host = u.hostname;
270	    const parts = host.split(".");
271	    const domain = parts.length > 2 ? parts.slice(-2).join(".") : host;
272	    return {
273	      scheme: `${u.protocol}//`,
274	      sub: host.slice(0, host.length - domain.length), // e.g. "newsnow.com."
275	      domain,                                          // the site you really land on
276	      rest: u.pathname === "/" && !u.search ? "" : u.pathname + u.search,
277	    };
278	  } catch (e) {
279	    return { scheme: "", sub: "", domain: text, rest: "" };
280	  }
281	}
282	
283	function linkLabel(s) {
284	  if (s.link_text) return s.link_text;
285	  const { rest } = parseLink(s.link);
286	  const hit = LINK_LABELS.find(([re]) => re.test(rest)) || LINK_LABELS.find(([re]) => re.test(s.link));
287	  return hit ? hit[1] : "Open link";
288	}
289	
290	function renderLink(s) {
291	  if (!s.link) return "";
292	  const hint = `<span class="link-hint"><span class="hint-hover">Hover</span><span class="hint-tap">Tap</span> to inspect</span>`;
293	  if (s.channel === "sms") {
294	    // Texts show the raw address, but tapping it still previews the real site.
295	    return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">${esc(s.link)}</button>${hint}</p>`;
296	  }
297	  return `<p class="link"><button type="button" class="link-chip" data-href="${esc(s.link)}">🔗 ${esc(linkLabel(s))}</button>${hint}</p>`;
298	}
299	
300	const peek = document.createElement("div");
301	peek.id = "link-peek";
302	peek.className = "link-peek";
303	peek.setAttribute("role", "tooltip");
304	peek.hidden = true;
305	document.body.appendChild(peek);
306	
307	let peekFor = null;     // the link the popup belongs to
308	let peekPinned = false; // true after a tap or click, so it stays open
309	
310	function showPeek(chip) {
311	  const p = parseLink(chip.dataset.href);
312	  peek.innerHTML = `
313	    <p class="peek-title">🔍 This link really goes to:</p>
314	    <p class="peek-url">${esc(p.scheme)}${p.sub ? `<span class="peek-sub">${esc(p.sub)}</span>` : ""}<b class="peek-domain">${esc(p.domain)}</b>${esc(p.rest)}</p>
315	    <p class="peek-tip">The real site is the last part of the address, right before the first /</p>`;
316	  peek.hidden = false;
317	  if (peekFor && peekFor !== chip) peekFor.removeAttribute("aria-describedby");
318	  peekFor = chip;
319	  chip.setAttribute("aria-describedby", "link-peek");
320	  placePeek();
321	}
322	
323	function hidePeek() {
324	  peek.hidden = true;
325	  peekPinned = false;
326	  if (peekFor) peekFor.removeAttribute("aria-describedby");
327	  peekFor = null;
328	}
329	
330	// Always open ABOVE the link, so it never covers the Phish / Legit buttons
331	// below the message (one column). On wide screens the buttons sit to the
332	// right of the message, so the popup also stays inside the message column.
333	// If the link is too close to the top of the screen, scroll up to make room.
334	function placePeek() {
335	  if (!peekFor || peek.hidden) return;
336	  if (!document.body.contains(peekFor)) return hidePeek();
337	  const gap = 8, edge = 12;
338	  const column = $("message").getBoundingClientRect();
339	  peek.style.maxWidth = `${Math.max(200, Math.min(360, column.width, window.innerWidth - 2 * edge))}px`;
340	  const w = peek.offsetWidth, h = peek.offsetHeight;
341	  let r = peekFor.getBoundingClientRect();
342	  const short = edge - (r.top - gap - h);
343	  if (short > 0 && window.scrollY > 0) {
344	    window.scrollBy(0, -Math.min(short, window.scrollY));
345	    r = peekFor.getBoundingClientRect();
346	  }
347	  const right = Math.min(window.innerWidth - edge, column.right);
348	  const top = Math.max(edge, r.top - gap - h);
349	  const left = Math.min(Math.max(edge, r.left), right - w);
350	  peek.style.top = `${top}px`;
351	  peek.style.left = `${Math.max(edge, left)}px`;
352	}
353	
354	const chipFrom = (e) => e.target.closest?.(".link-chip");
355	
356	document.addEventListener("mouseover", (e) => {
357	  const chip = chipFrom(e);
358	  if (chip && !peekPinned) showPeek(chip);
359	});
360	document.addEventListener("mouseout", (e) => {
361	  const chip = chipFrom(e);
362	  if (chip && !peekPinned && !chip.contains(e.relatedTarget)) hidePeek();
363	});
364	document.addEventListener("focusin", (e) => {
365	  const chip = chipFrom(e);
366	  if (chip) showPeek(chip);
367	});
368	document.addEventListener("focusout", (e) => {
369	  if (chipFrom(e) && !peekPinned) hidePeek();
370	});
371	document.addEventListener("click", (e) => {
372	  const chip = chipFrom(e);
373	  if (chip) {
374	    e.preventDefault();
375	    if (peekPinned && peekFor === chip) return hidePeek();
376	    showPeek(chip);
377	    peekPinned = true;
378	  } else if (peekPinned && !peek.contains(e.target)) {
379	    hidePeek();
380	  }
381	});
382	document.addEventListener("keydown", (e) => { if (e.key === "Escape") hidePeek(); });
383	window.addEventListener("scroll", placePeek, { passive: true });
384	window.addEventListener("resize", placePeek);
385	
386	function renderMessage(s) {
387	  const link = renderLink(s);
388	  const clock = clockFor(s);
389	
390	  if (s.channel === "sms") {
391	    return `<div class="sms">
392	      <div class="status-bar">
393	        <span class="sb-time">${esc(clock.short)}</span>
394	        <span class="sb-right">
395	          <span class="signal" aria-hidden="true"><i></i><i></i><i></i><i></i></span>
396	          <span class="battery" aria-hidden="true"><span class="bat-fill"></span></span>
397	        </span>
398	      </div>
399	      <p class="label">💬 Text message from <b>${esc(s.sender)}</b></p>
400	      <p class="bubble">${esc(s.body)}</p>${link}</div>`;
401	  }
402	
403	  return `<div class="email">
404	    <div class="email-head">
405	      <div class="avatar" aria-hidden="true">${esc(initialOf(s.sender))}</div>
406	      <div class="email-who">
407	        <p class="from"><b>From:</b> ${esc(s.sender)}</p>
408	        <p class="subject">${esc(s.subject || "(no subject)")}</p>
409	      </div>
410	      <p class="email-time">${esc(clock.long)}</p>
411	    </div>
412	    <p class="body">${esc(s.body)}</p>${link}
413	    <div class="email-actions">
414	      <button type="button" disabled>↩ Reply</button>
415	      <button type="button" disabled>↪ Forward</button>
416	    </div>
417	  </div>`;
418	}
419	
420	// Red flags arrive as one string with semicolons between them.
421	function flagList(red_flags) {
422	  const parts = Array.isArray(red_flags) ? red_flags : String(red_flags || "").split(";");
423	  return parts.map((f) => String(f).trim()).filter(Boolean);
424	}
425	
426	function floatScore(text) {
427	  if (calmMode()) return;
428	  const bit = document.createElement("span");
429	  bit.className = "pop-score";
430	  bit.textContent = text;
431	  $("pop-layer").appendChild(bit);
432	  setTimeout(() => bit.remove(), 1500);
433	}
434	
435	// ---------- Answer reactions: hooked, dodged, too cautious, safe ----------
436	const REACTIONS = {
437	  hooked:   "🎣 You got hooked!",
438	  dodged:   "✅ You dodged the hook!",
439	  cautious: "🤔 Too cautious! This one was safe.",
440	  safe:     "✅ Correct, this one's safe.",
441	};
442	
443	// Which of the 4 reactions fits: the real answer vs. the player's guess.
444	function reactionFor(r, guess) {
445	  const real = String(r.game_answer || "").toLowerCase();
446	  const said = guess.toLowerCase();
447	  if (real === "phish") return said === "phish" ? "dodged" : "hooked";
448	  if (real === "legit") return said === "legit" ? "safe" : "cautious";
449	  return r.correct ? "safe" : "hooked";
450	}
451	
452	function showReaction(kind) {
453	  const el = $("reaction");
454	  el.textContent = REACTIONS[kind];
455	  el.className = `reaction ${kind}`;
456	}
457	
458	// The hook and line, drawn as inline SVG (a dark outline under a light
459	// stroke, so it shows up over both the navy page and the white email).
460	const HOOK_SVG = `<svg class="hook" width="34" height="48" viewBox="0 0 34 48" aria-hidden="true">
461	  <g fill="none" stroke-linecap="round" stroke-linejoin="round">
462	    <g stroke="#0a1a33" stroke-width="5.5"><circle cx="20" cy="5" r="3.5"/><path d="M20 8.5V32a9 9 0 0 1-18 0v-8l5 5"/></g>
463	    <g stroke="#e9f1f7" stroke-width="3"><circle cx="20" cy="5" r="3.5"/><path d="M20 8.5V32a9 9 0 0 1-18 0v-8l5 5"/></g>
464	  </g>
465	</svg>`;
466	
467	// The rig hangs from the top of the visible screen. It lives in page
468	// coordinates, so it stays lined up with the card even if the page scrolls.
469	function makeRig(x, drop) {
470	  const rig = document.createElement("div");
471	  rig.className = "hook-rig";
472	  rig.setAttribute("aria-hidden", "true");
473	  rig.style.left = `${x + window.scrollX}px`;
474	  rig.style.top = `${window.scrollY}px`;
475	  rig.style.setProperty("--drop", `${drop}px`);
476	  rig.innerHTML = `<span class="hook-line"></span>${HOOK_SVG}`;
477	  document.body.appendChild(rig);
478	  return rig;
479	}
480	
481	const done = (anim) => anim.finished.catch(() => {});
482	
483	// Where the hook should aim: the top of the visible part of the message.
484	function cardTarget() {
485	  const card = $("message");
486	  const box = (card.firstElementChild || card).getBoundingClientRect();
487	  return { card, box, top: Math.max(box.top, 12), x: box.left + box.width / 2 };
488	}
489	
490	// Phish, player said Legit: the hook drops, bites, and yanks the card away.
491	async function playHooked() {
492	  const { card, box, top, x } = cardTarget();
493	  const drop = Math.max(top - 26, 4);   // hook's bend lands just inside the card's top edge
494	  const above = drop + 60;              // far enough up to start off screen
495	  const lift = box.bottom + 80;         // far enough up to leave the screen
496	  const rig = makeRig(x, drop);
497	  const pull = "cubic-bezier(0.55, 0, 0.8, 0.2)";
498	
499	  card.classList.add("hook-anim");
500	  card.style.transformOrigin = `50% ${top - card.getBoundingClientRect().top + 14}px`;
501	
502	  const opts = { duration: 1250, fill: "forwards" };
503	  const rigAnim = rig.animate([
504	    { transform: `translateY(${-above}px)`, easing: "cubic-bezier(0.3, 0.6, 0.4, 1)" },
505	    { transform: "translateY(0px)", offset: 0.34 },
506	    { transform: "translateY(7px)", offset: 0.42 },
507	    { transform: "translateY(0px)", offset: 0.5, easing: pull },
508	    { transform: `translateY(${-lift}px)` },
509	  ], opts);
510	  const cardAnim = card.animate([
511	    { transform: "translateY(0px) rotate(0deg)" },
512	    { transform: "translateY(0px) rotate(0deg)", offset: 0.34 },
513	    { transform: "translateY(7px) rotate(0deg)", offset: 0.42 },
514	    { transform: "translateY(0px) rotate(-2deg)", offset: 0.5, easing: pull },
515	    { transform: `translateY(${-lift}px) rotate(-4deg)` },
516	  ], opts);
517	
518	  await Promise.all([done(rigAnim), done(cardAnim)]);
519	  rig.remove();
520	
521	  // Bring the message back so the player can read it next to the explanation.
522	  const back = card.animate(
523	    [{ opacity: 0, transform: "translateY(-12px)" }, { opacity: 1, transform: "none" }],
524	    { duration: 280, easing: "ease-out" }
525	  );
526	  cardAnim.cancel();
527	  done(back).then(() => card.classList.remove("hook-anim"));
528	}
529	
530	// Phish, player said Phish: the hook swings down, the card ducks, the hook misses.
531	async function playDodged() {
532	  const { card, top, x } = cardTarget();
533	  const drop = Math.max(top - 36, 4);   // would just graze the card if it stayed put
534	  const above = drop + 60;
535	  const rig = makeRig(x, drop);
536	
537	  card.classList.add("hook-anim");
538	
539	  const opts = { duration: 1100 };
540	  const rigAnim = rig.animate([
541	    { transform: `translateY(${-above}px) rotate(0deg)`, easing: "ease-out" },
542	    { transform: "translateY(0px) rotate(0deg)", offset: 0.3 },
543	    { transform: "translateY(0px) rotate(4deg)", offset: 0.42 },
544	    { transform: "translateY(0px) rotate(-3deg)", offset: 0.54 },
545	    { transform: "translateY(0px) rotate(0deg)", offset: 0.64, easing: "ease-in" },
546	    { transform: `translateY(${-above}px) rotate(0deg)` },
547	  ], { ...opts, fill: "forwards" });
548	  const cardAnim = card.animate([
549	    { transform: "translateY(0px) scale(1)" },
550	    { transform: "translateY(0px) scale(1)", offset: 0.16 },
551	    { transform: "translateY(18px) scale(0.98)", offset: 0.3 },
552	    { transform: "translateY(18px) scale(0.98)", offset: 0.62 },
553	    { transform: "translateY(0px) scale(1)", offset: 0.82 },
554	    { transform: "translateY(0px) scale(1)" },
555	  ], opts);
556	
557	  await Promise.all([done(rigAnim), done(cardAnim)]);
558	  rig.remove();
559	  card.classList.remove("hook-anim");
560	}
