607	      : "";
608	    $("result").innerHTML = `
609	      <h3>This one was <b>${esc(r.game_answer)}</b>.</h3>
610	      ${flags}<p>${esc(r.explanation)}</p>${went}${nudge}`;
611	    $("result").className = `ps-card ${kind === "hooked" ? "bad" : kind === "cautious" ? "gentle" : "good"}`;
612	    $("progress").textContent = `${mode.toUpperCase()} · Round ${round} of ${ROUNDS} · ${correct} correct`;
