729	          .map((m) => `<span class="lb-badge" title="${BADGES[m]} badge">${badgeIcon(m)}</span>`).join("");
730	        const master = ALL_MODES.every((b) => p.badges.includes(b)) ? " 🏆" : "";
731	        return `<li><b>${esc(p.username)}</b> ${icons}${master} <span class="lb-score">${p.total_score} pts</span></li>`;
732	      }).join("")
733	    : '<li class="empty">No scores yet. Be the first!</li>';
