// Mission-screen tutorial: fresh state per viewport.
const puppeteer = require("puppeteer-core");
const OUT = __dirname;
const VIEWPORTS = [
  { name: "desktop", width: 1920, height: 1080 },
  { name: "phone", width: 375, height: 812, isMobile: true, hasTouch: true, deviceScaleFactor: 2 },
];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let fails = 0;
const check = (ok, msg) => { if (!ok) fails++; console.log(`${ok ? "PASS" : "FAIL"} ${msg}`); };

(async () => {
  const browser = await puppeteer.launch({ executablePath: "C:/Program Files/Google/Chrome/Application/chrome.exe", headless: "new" });
  for (const vp of VIEWPORTS) {
    const ctx = await browser.createBrowserContext();
    const page = await ctx.newPage();
    const errors = [];
    page.on("pageerror", (e) => errors.push(e.message));
    await page.setViewport(vp);
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
    await page.evaluate(() => { localStorage.removeItem("ps-tutorial-seen-v2"); localStorage.setItem("ps-tutorial-seen", "1"); });

    const st = () => page.evaluate(() => {
      const t = document.querySelector(".tutorial");
      const r = t.getBoundingClientRect();
      const tg = document.querySelector(".tut-target");
      return {
        shown: !t.hidden, screen: document.body.dataset.screen,
        count: t.querySelector(".tut-count")?.textContent,
        target: tg ? (tg.closest("#sample-message, #sample-answers") ? "sample:" : tg.closest("#play-screen") ? "play:" : "?:") + [...tg.classList].filter((k) => k !== "tut-target").join(".") || tg.tagName : null,
        inView: r.left >= 0 && r.top >= 0 && r.right <= document.documentElement.clientWidth && r.bottom <= innerHeight,
        hScroll: document.documentElement.scrollWidth > document.documentElement.clientWidth,
        seen: localStorage.getItem("ps-tutorial-seen-v2"),
      };
    });
    const toMission = async () => {
      await page.click('.mode[data-mode="easy"]');
      await sleep(900);
    };

    // 1. New player (old in-game flag set, new one not): tutorial starts on the briefing
    await page.type("#username", "NewPlayer");
    await toMission();
    const steps = [];
    for (let i = 1; i <= 3; i++) {
      const s = await st();
      steps.push(s);
      await page.screenshot({ path: `${OUT}/mission-${vp.name}-${i}.png` });
      if (!s.shown) break;
      if (i === 2 && vp.name === "desktop") {   // hovering the sample link shows the peek inside the sample
        await page.hover("#sample-message .link-chip");
        await sleep(200);
        const peek = await page.evaluate(() => {
          const p = document.getElementById("link-peek"), r = p.getBoundingClientRect();
          const col = document.querySelector("#sample-message .email").getBoundingClientRect();
          return { shown: !p.hidden, inside: r.left >= col.left - 1 && r.right <= col.right + 1 && r.width > 0 };
        });
        check(peek.shown && peek.inside, `${vp.name} sample link peek opens inside the sample: ${JSON.stringify(peek)}`);
        await page.screenshot({ path: `${OUT}/mission-${vp.name}-peek.png` });
        await page.mouse.move(5, 5);
      }
      await page.click(".tut-ok");
      await sleep(150);
    }
    console.log(vp.name, steps.map((s) => `${s.count} -> ${s.target} inView=${s.inView} seen=${s.seen}`).join(" | "));
    const done = await st();
    check(steps.length === 3 && steps.every((s) => s.shown && s.inView && !s.hScroll && s.screen === "mission-screen" && s.seen === null && s.target?.startsWith("sample:")),
      `${vp.name} briefing tutorial shows 3 tips on the sample, on screen, flag unsaved until done`);
    check(!done.shown && done.seen === "1", `${vp.name} finishing saves the flag`);

    // 2. Live game: no automatic tutorial
    await page.click("#btn-start");
    await page.waitForSelector("#message .email, #message .sms");
    await sleep(1200);
    check(!(await st()).shown, `${vp.name} no automatic tutorial in the live game`);

    // 3. "?" during play still works on the real message
    await page.click("#btn-tutorial");
    await sleep(200);
    const q = await st();
    check(q.shown && q.target?.startsWith("play:"), `${vp.name} "?" replays on the live message (${q.target})`);
    await page.click(".tut-skip");

    // 4. Back on the briefing after finishing: no auto start, "Show me again" works
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
    await page.type("#username", "NewPlayer");
    await toMission();
    check(!(await st()).shown, `${vp.name} no auto start once seen`);
    await page.click("#btn-mission-tutorial");
    await sleep(200);
    check((await st()).shown, `${vp.name} "Show me again" replays it`);

    // 5. Fresh player who clicks Start mission mid-tutorial: not saved, shows again next time
    await page.evaluate(() => localStorage.removeItem("ps-tutorial-seen-v2"));
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
    await page.type("#username", "Other");
    await toMission();
    const mid = await st();
    await page.click("#btn-start");
    await sleep(300);
    const after = await st();
    check(mid.shown && !after.shown && after.seen === null, `${vp.name} Start mission mid-tutorial closes it without saving`);
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
    await page.type("#username", "Other");
    await toMission();
    check((await st()).shown, `${vp.name} it shows again on the next briefing`);
    await page.click(".tut-skip");
    check((await st()).seen === "1", `${vp.name} Skip saves the flag`);
    check(!errors.length, `${vp.name} no page errors ${errors.join("; ")}`);
    await ctx.close();
  }
  await browser.close();
  console.log(fails ? `${fails} FAILED` : "ALL PASSED");
})();

