  background: transparent; color: var(--teal); border: 2px solid var(--navy-2);
}
.help-toggle:hover, .help-toggle.open { border-color: var(--teal); }
.help-toggle.open { background: rgba(45, 224, 196, 0.12); }

/* The callout: a small card with a teal edge and an arrow pointing at its target.
   It floats in open space next to the target (data-side says which side it's on).
   When there's no open space, it sits in the page flow under the target
   (.tut-inline) and pushes the content below it down instead of covering it. */
.tutorial {
  position: fixed; z-index: 1100; left: 0; top: 0;
  width: min(300px, calc(100vw - 24px));
  padding: 14px 16px; border-radius: 14px;
  background: var(--navy-2); color: var(--text);
  border: 2px solid var(--teal);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.5);
  text-align: left;
  animation: tut-in 0.18s ease-out;
}
.tutorial.tut-inline {
  position: relative; left: auto; top: auto; z-index: 5;
  width: auto; max-width: 360px; margin: 14px 12px 12px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.3);
}
/* In the play column the grid rules set the width; just keep the gap */
#play-screen .play-side > .tutorial.tut-inline { max-width: none; }
.tutorial p { margin: 0; }
.tut-count {
  margin-bottom: 6px !important; font-size: 12px; font-weight: 600;
  letter-spacing: 2px; text-transform: uppercase; color: var(--teal);
}
.tut-text { font-size: 15px; line-height: 1.45; }
.tut-actions { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 12px; }
.tut-skip {
  padding: 4px 0; background: none; color: var(--muted);
  font-size: 13px; font-weight: 600; text-decoration: underline; text-underline-offset: 3px;
}
.tut-skip:hover { color: var(--text); }
.tut-ok { padding: 8px 18px; font-size: 14px; }
.tut-skip:focus-visible, .tut-ok:focus-visible { outline: 2px solid var(--text); outline-offset: 2px; }

/* The arrow is a turned square with two teal edges; the corner they share points at the target */
.tut-arrow {
  position: absolute; width: 14px; height: 14px;
  background: var(--navy-2); border: 2px solid var(--teal);
}
.tutorial[data-side="below"] .tut-arrow,
.tutorial[data-side="above"] .tut-arrow { left: var(--arrow-x, 50%); transform: translateX(-50%) rotate(45deg); }
.tutorial[data-side="left"] .tut-arrow,
.tutorial[data-side="right"] .tut-arrow { top: var(--arrow-y, 50%); transform: translateY(-50%) rotate(45deg); }
.tutorial[data-side="below"] .tut-arrow { top: -9px; border-right: 0; border-bottom: 0; }   /* points up */
.tutorial[data-side="above"] .tut-arrow { bottom: -9px; border-left: 0; border-top: 0; }   /* points down */
.tutorial[data-side="right"] .tut-arrow { left: -9px; border-top: 0; border-right: 0; }     /* points left */
.tutorial[data-side="left"] .tut-arrow { right: -9px; border-bottom: 0; border-left: 0; }   /* points right */
@keyframes tut-in {
  from { opacity: 0; }
}

/* Tight ring around the thing the callout points at.
   The sender line and contact name shrink to their text, so the ring fits them. */
.email-who .from { width: fit-content; max-width: 100%; }
.sms .label b { width: fit-content; max-width: 100%; margin: 0 auto; }
.tut-target { outline: 2px solid var(--teal) !important; outline-offset: 2px; border-radius: 4px; }
