  let spot = findTutorialSpot(r, w, h);
  if (!spot) {
    // Scroll to open up room below, then above, the target
    const startY = window.scrollY;
    for (const dy of [r.bottom + TUT_GAP + h + TUT_EDGE - vh, r.top - TUT_GAP - h - TUT_EDGE]) {
