      if (Math.abs(window.scrollY - startY) < 1) continue;   // the page can't scroll that way
      r = rect();
      spot = findTutorialSpot(r, w, h);
      if (spot) break;
      window.scrollTo(0, startY);
    }
    r = rect();
  }
  if (spot) applyFloat(spot, r, w, h);
  else applyInline(tutTarget);
