// Callout placement test: fresh state, forced scenarios, three screen sizes.
const puppeteer = require("puppeteer-core");
const OUT = __dirname;
const VIEWPORTS = [
  { name: "1920", width: 1920, height: 1080 },
  { name: "1366", width: 1366, height: 768 },
  { name: "375", width: 375, height: 812, isMobile: true, hasTouch: true, deviceScaleFactor: 2 },
];
const CASES = [
  { id: 2, label: "email-link" },
  { id: 1, label: "email-nolink" },
  { id: 3, label: "sms-link" },
  { id: 8, label: "sms-nolink" },
];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let fails = 0;
const check = (ok, msg) => { if (!ok) fails++; console.log(`${ok ? "PASS" : "FAIL"} ${msg}`); };

// Runs in the page: where is the callout, what (if anything) does it cover?
const inspect = () => {
  const t = document.querySelector(".tutorial");
  const c = t.getBoundingClientRect();
  const tg = document.querySelector(".tut-target");
  const vw = document.documentElement.clientWidth, vh = innerHeight;
  const hit = (r) => r.width >= 1 && r.height >= 1 && r.left < c.right && r.right > c.left && r.top < c.bottom && r.bottom > c.top;
  const covered = [];
  const range = document.createRange();
  document.querySelectorAll("h1,h2,h3,p,li,th,td,.brand-name,.email-time,.link-hint,.streak").forEach((el) => {
    if (t.contains(el) || el.closest(".ocean-bg")) return;
    range.selectNodeContents(el);
    if ([...range.getClientRects()].some(hit)) covered.push(`${el.tagName.toLowerCase()}.${el.className || ""} "${el.textContent.trim().slice(0, 24)}"`);
  });
  document.querySelectorAll("button,input,img,.avatar,.dot,.answer,.status-bar").forEach((el) => {
    if (t.contains(el) || el.closest(".ocean-bg")) return;
    if (hit(el.getBoundingClientRect())) covered.push(`${el.tagName.toLowerCase()}.${el.className || ""}`);
  });
  if (tg && hit(tg.getBoundingClientRect())) covered.push("THE TARGET");
  // Tight ring: the target is no wider than its content needs
  let tight = null;
  if (tg) {
    const tr = tg.getBoundingClientRect();
    range.selectNodeContents(tg);
    const cr = range.getBoundingClientRect();
    tight = tg.matches(".answers, .body, .bubble") ? true : tr.width <= cr.width + 4;
  }
  // Does the arrow sit next to the target, pointing at it?
  let arrowOk = null;
  const a = t.querySelector(".tut-arrow");
  if (a && tg) {
    const ar = a.getBoundingClientRect(), tr = tg.getBoundingClientRect();
    const ax = ar.left + ar.width / 2, ay = ar.top + ar.height / 2, side = t.dataset.side;
    if (side === "below" || side === "above") arrowOk = ax >= tr.left - 2 && ax <= tr.right + 2 && (side === "below" ? ay > tr.bottom - 2 : ay < tr.top + 2);
    else arrowOk = ay >= tr.top - 2 && ay <= tr.bottom + 2 && (side === "right" ? ax > tr.right - 2 : ax < tr.left + 2);
    arrowOk = arrowOk && Math.min(Math.abs(ay - tr.bottom), Math.abs(ay - tr.top), Math.abs(ax - tr.left), Math.abs(ax - tr.right)) < 40;
  }
  return {
    shown: !t.hidden,
    count: t.querySelector(".tut-count")?.textContent,
    mode: t.classList.contains("tut-inline") ? "inline" : "float", side: t.dataset.side,
    target: tg ? `${tg.tagName.toLowerCase()}.${[...tg.classList].filter((k) => k !== "tut-target").join(".")}` : null,
    onScreen: c.left >= 0 && c.top >= 0 && c.right <= vw && c.bottom <= vh,
    targetOnScreen: tg ? (() => { const r = tg.getBoundingClientRect(); return r.top >= 0 && r.bottom <= vh; })() : null,
    hScroll: document.documentElement.scrollWidth > vw,
    covered, tight, arrowOk,
    seen: localStorage.getItem("ps-tutorial-seen-v3"),
  };
};

(async () => {
  const browser = await puppeteer.launch({ executablePath: "C:/Program Files/Google/Chrome/Application/chrome.exe", headless: "new" });
  for (const vp of VIEWPORTS) {
    for (const c of CASES) {
      const ctx = await browser.createBrowserContext();
      const page = await ctx.newPage();
      const errors = [];
      page.on("pageerror", (e) => errors.push(e.message));
      await page.setViewport(vp);
      await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
      await page.evaluate((id) => {
        localStorage.removeItem("ps-tutorial-seen-v3");
        const keep = MOCK_SCENARIOS.filter((s) => s.scenario_id === id).map((s) => ({ ...s, difficulty: "easy" }));
        MOCK_SCENARIOS.splice(0, MOCK_SCENARIOS.length, ...keep);
      }, c.id);
      await page.type("#username", "NewPlayer");
      await page.click('.mode[data-mode="easy"]');
      await sleep(300);

      if (c.id === 2) {   // mission screen is back to normal (checked once per size)
        const m = await page.evaluate(() => ({
          sample: !!document.querySelector("#sample-message, .practice, #btn-mission-tutorial"),
          tutorialShown: !document.querySelector(".tutorial").hidden,
          scrolls: document.documentElement.scrollHeight > innerHeight + 1,
          cards: [...document.querySelectorAll("#mission-screen .ps-card")].map((e) => e.className),
        }));
        check(!m.sample && !m.tutorialShown, `${vp.name} mission screen: no example inbox, no tutorial (${m.cards.join(" | ")})`);
        if (vp.name !== "375") check(!m.scrolls, `${vp.name} mission screen fits without scrolling`);
        await page.screenshot({ path: `${OUT}/place-${vp.name}-mission.png` });
      }

      await page.click("#btn-start");
      await page.waitForSelector("#message .email, #message .sms");
      await sleep(900);
      const steps = [];
      for (let i = 1; i <= 3; i++) {
        const s = await page.evaluate(inspect);
        steps.push(s);
        await page.screenshot({ path: `${OUT}/place-${vp.name}-${c.label}-${i}.png` });
        if (!s.shown) break;
        await page.click(".tut-ok");
        await sleep(200);
      }
      const ok = steps.length === 3 && steps.every((s) => s.shown && s.onScreen && s.targetOnScreen && !s.hScroll && !s.covered.length && s.tight && s.arrowOk && s.seen === null);
      check(ok && !errors.length, `${vp.name} ${c.label}: ` + steps.map((s) => s.shown
        ? `${s.count} ${s.target} [${s.mode}/${s.side}]${s.onScreen ? "" : " OFF-SCREEN"}${s.targetOnScreen ? "" : " TARGET-OFF"}${s.tight ? "" : " LOOSE-RING"}${s.arrowOk ? "" : " ARROW-OFF"}${s.covered.length ? " COVERS " + s.covered.join(", ") : ""}`
        : "not shown").join(" | ") + (errors.length ? " ERRORS " + errors.join("; ") : ""));
      const end = await page.evaluate(inspect);
      if (!(!end.shown && end.seen === "1")) check(false, `${vp.name} ${c.label} finishing should hide and save (shown=${end.shown} seen=${end.seen})`);
      // Inline callout must leave the message as it was
      const restored = await page.evaluate(() => document.querySelector(".tutorial").parentElement === document.body && !document.querySelector("#message .tutorial"));
      if (!restored) check(false, `${vp.name} ${c.label} callout not moved back out of the message`);
      await ctx.close();
    }

    // Round 2 doesn't auto-start; "?" replays; skip saves
    const ctx = await browser.createBrowserContext();
    const page = await ctx.newPage();
    await page.setViewport(vp);
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
    await page.type("#username", "NewPlayer");
    await page.click('.mode[data-mode="easy"]');
    await page.click("#btn-start");
    await page.waitForSelector("#message .email, #message .sms");
    await sleep(900);
    const r1 = await page.evaluate(inspect);
    await page.click("#btn-phish");   // answering closes it without saving
    await sleep(1800);
    const afterAnswer = await page.evaluate(inspect);
    await page.click("#btn-next");
    await page.waitForSelector("#message .email, #message .sms");
    await sleep(900);
    const r2 = await page.evaluate(inspect);
    await page.click("#btn-tutorial");
    await sleep(300);
    const replay = await page.evaluate(inspect);
    await page.click(".tut-skip");
    const skipped = await page.evaluate(inspect);
    check(r1.shown && !afterAnswer.shown && afterAnswer.seen === null && !r2.shown && replay.shown && !replay.covered.length && !skipped.shown && skipped.seen === "1",
      `${vp.name} flow: round 1 auto=${r1.shown}, answering closes unsaved=${!afterAnswer.shown && afterAnswer.seen === null}, round 2 auto=${r2.shown}, "?" replays=${replay.shown} covers=[${replay.covered}], skip saves=${skipped.seen === "1"}`);
    await ctx.close();
  }
  await browser.close();
  console.log(fails ? `${fails} FAILED` : "ALL PASSED");
})();

