// Six-step mission tutorial: fresh state, three screen sizes.
const puppeteer = require("puppeteer-core");
const OUT = __dirname;
const KEY = "ps-tutorial-seen-v4";
const VIEWPORTS = [
  { name: "1920", width: 1920, height: 1080 },
  { name: "1366", width: 1366, height: 768 },
  { name: "375", width: 375, height: 812, isMobile: true, hasTouch: true, deviceScaleFactor: 2 },
];
const EXPECT = [
  ["p.from", "Check who it's really from. Compare it to your trusted contacts."],
  ["div.ps-card.contacts", "These are the real websites and phone numbers. If a message doesn't match, be suspicious."],
  ["button.link-chip", "a link to see where it really goes. Look at the main domain."],
  ["div.answers.sample-answers", "Decide: Phish or Legit? On a keyboard, use ← for Phish and → for Legit."],
  ["div.dots.sample-dots", "✓ means you got it right, ✗ means you got hooked or were too cautious."],
  ["button.help-toggle", "Press ? anytime to replay this tutorial."],
];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let fails = 0;
const check = (ok, msg) => { if (!ok) fails++; console.log(`${ok ? "PASS" : "FAIL"} ${msg}`); };

const inspect = () => {
  const t = document.querySelector(".tutorial");
  const c = t.getBoundingClientRect();
  const tg = document.querySelector(".tut-target");
  const vw = document.documentElement.clientWidth, vh = innerHeight;
  const hit = (r) => r.width >= 1 && r.height >= 1 && r.left < c.right && r.right > c.left && r.top < c.bottom && r.bottom > c.top;
  const covered = [];
  const range = document.createRange();
  document.querySelectorAll("h1,h2,h3,p,li,th,td,.brand-name,.email-time,.link-hint,.streak,.sample-progress-label").forEach((el) => {
    if (t.contains(el) || el.closest(".ocean-bg")) return;
    range.selectNodeContents(el);
