    const ax = a.left + a.width / 2, ay = a.top + a.height / 2, side = t.dataset.side;
    if (side === "below" || side === "above") arrowOk = ax >= tr.left - 2 && ax <= tr.right + 2 && (side === "below" ? ay > tr.bottom - 2 : ay < tr.top + 2);
    else arrowOk = ay >= tr.top - 2 && ay <= tr.bottom + 2 && (side === "right" ? ax > tr.right - 2 : ax < tr.left + 2);
    arrowOk = arrowOk && Math.min(Math.abs(ay - tr.bottom), Math.abs(ay - tr.top), Math.abs(ax - tr.left), Math.abs(ax - tr.right)) < 40;
  }
  // Mission row: nothing overlapping between the contacts column and the example card
  const rowsOk = (() => {
    const cols = [...document.querySelectorAll("#mission-screen > [class*=col]")].map((e) => e.getBoundingClientRect()).filter((r) => r.height);
    for (let i = 0; i < cols.length; i++) for (let j = i + 1; j < cols.length; j++) {
      const a = cols[i], b = cols[j];
      if (a.left < b.right - 1 && a.right > b.left + 1 && a.top < b.bottom - 1 && a.bottom > b.top + 1) return false;
    }
    const kids = [...document.querySelectorAll("#mission-screen > [class*=col]")];
    return kids.every((col) => [...col.children].every((ch) => { const r = ch.getBoundingClientRect(), p = col.getBoundingClientRect(); return !r.height || r.bottom <= p.bottom + 1; }));
  })();
  return {
    shown: !t.hidden, screen: document.body.dataset.screen,
    count: t.querySelector(".tut-count")?.textContent, text: t.querySelector(".tut-text")?.textContent,
    mode: t.classList.contains("tut-inline") ? "inline" : "float", side: t.dataset.side,
    target: tg ? `${tg.tagName.toLowerCase()}.${[...tg.classList].filter((k) => k !== "tut-target" && k !== "open").join(".")}` : null,
    onScreen: c.left >= 0 && c.top >= 0 && c.right <= vw && c.bottom <= vh,
    targetOnScreen: tg ? (() => { const r = tg.getBoundingClientRect(); return r.top >= 0 && r.bottom <= vh; })() : null,
    hScroll: document.documentElement.scrollWidth > vw,
    covered, tight, arrowOk, rowsOk,
    focusOk: document.activeElement?.classList.contains("tut-ok"),
    seen: localStorage.getItem("ps-tutorial-seen-v4"),
  };
};

(async () => {
  const browser = await puppeteer.launch({ executablePath: "C:/Program Files/Google/Chrome/Application/chrome.exe", headless: "new" });
  for (const vp of VIEWPORTS) {
    const ctx = await browser.createBrowserContext();
    const page = await ctx.newPage();
    const errors = [];
    page.on("pageerror", (e) => errors.push(e.message));
    await page.setViewport(vp);
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
    await page.evaluate((k) => localStorage.removeItem(k), KEY);
    await page.type("#username", "NewPlayer");
    await page.click('.mode[data-mode="easy"]');
    await sleep(900);

    const steps = [];
    for (let i = 1; i <= 6; i++) {
      const s = await page.evaluate(inspect);
      steps.push(s);
      await page.screenshot({ path: `${OUT}/six-${vp.name}-${i}.png` });
      if (!s.shown) break;
      // Alternate: Enter (focus on Got it), then Enter with focus moved off the callout, then click
      if (i === 2) { await page.evaluate(() => document.activeElement.blur()); await page.keyboard.press("Enter"); }
      else if (i % 2) await page.keyboard.press("Enter");
      else await page.click(".tut-ok");
      await sleep(200);
    }
    steps.forEach((s, i) => {
      const [tgt, text] = EXPECT[i];
      const ok = s.shown && s.screen === "mission-screen" && s.count === `Tip ${i + 1} of 6` && s.target === tgt && s.text.endsWith(text) &&
        s.onScreen && s.targetOnScreen && !s.hScroll && !s.covered.length && s.tight && s.arrowOk && s.rowsOk && s.focusOk && s.seen === null;
      check(ok, `${vp.name} ${s.count || "step " + (i + 1)} -> ${s.target} [${s.mode}/${s.side}]` +
        `${s.target === tgt ? "" : " WRONG-TARGET(" + tgt + ")"}${s.text?.endsWith(text) ? "" : " WRONG-TEXT: " + s.text}` +
        `${s.onScreen ? "" : " OFF-SCREEN"}${s.targetOnScreen ? "" : " TARGET-OFF"}${s.tight ? "" : " LOOSE"}${s.arrowOk ? "" : " ARROW-OFF"}` +
        `${s.rowsOk ? "" : " ROW-OVERLAP"}${s.focusOk ? "" : " NO-FOCUS"}${s.hScroll ? " H-SCROLL" : ""}${s.seen === null ? "" : " SAVED-EARLY"}` +
        `${s.covered.length ? " COVERS " + s.covered.join(", ") : ""}`);
    });
    if (steps.length < 6) check(false, `${vp.name} only ${steps.length} steps shown`);
    const done = await page.evaluate(inspect);
    check(!done.shown && done.seen === "1", `${vp.name} finishing hides it and saves the flag`);

    // Header "?" replays; Escape skips (saves)
    await page.evaluate(() => scrollTo(0, 0));
    await page.click("#btn-tutorial");
    await sleep(300);
    const replay = await page.evaluate(inspect);
    await page.keyboard.press("Escape");
    const esc = await page.evaluate(inspect);
    check(replay.shown && replay.count === "Tip 1 of 6" && !esc.shown, `${vp.name} "?" replays from tip 1, Escape closes`);

    // Start mission: no tutorial on the play screen, "?" hidden there, arrow keys answer
    await page.click("#btn-start");
    await page.waitForSelector("#message .email, #message .sms");
    await sleep(900);
    const play = await page.evaluate(() => ({
      shown: !document.querySelector(".tutorial").hidden,
      helpVisible: !!document.getElementById("btn-tutorial").offsetParent,
    }));
    await page.keyboard.press("ArrowLeft");
    await sleep(1800);
    const answered = await page.evaluate(() => ({ reaction: document.getElementById("reaction").textContent, next: !document.getElementById("btn-next").classList.contains("hidden") }));
    await page.keyboard.press("ArrowRight");   // ignored once answered
    await sleep(200);
    const dots = await page.evaluate(() => document.querySelectorAll("#dots .dot.correct, #dots .dot.wrong").length);
    check(!play.shown && !play.helpVisible && answered.reaction && answered.next && dots === 1,
      `${vp.name} play screen: no tutorial=${!play.shown}, "?" hidden=${!play.helpVisible}, ← answered ("${answered.reaction}"), → ignored after answering=${dots === 1}`);

    // A player who leaves mid-tutorial isn't marked as seen
    await page.evaluate((k) => localStorage.removeItem(k), KEY);
    await page.goto("http://localhost:5517/", { waitUntil: "networkidle0" });
    await page.type("#username", "Other");
    await page.click('.mode[data-mode="easy"]');
    await sleep(900);
    const mid = await page.evaluate(inspect);
    await page.click("#btn-back");
    const left = await page.evaluate(inspect);
    await page.click('.mode[data-mode="easy"]');
    await sleep(900);
    const again = await page.evaluate(inspect);
    await page.click(".tut-skip");
    const skipped = await page.evaluate(inspect);
    check(mid.shown && !left.shown && left.seen === null && again.shown && !skipped.shown && skipped.seen === "1",
      `${vp.name} leaving mid-tutorial doesn't save; it shows again; Skip saves`);
    check(!errors.length, `${vp.name} no page errors ${errors.join("; ")}`);
    await ctx.close();
  }
  await browser.close();
  console.log(fails ? `${fails} FAILED` : "ALL PASSED");
})();
